"""Single-page command center for the hackathon demo."""

PAGE = r'''<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>NightShift — Autonomous maintenance</title><style>
@import url('https://fonts.googleapis.com/css2?family=DM+Mono:wght@400;500&family=Manrope:wght@500;600;700;800&display=swap');
*{box-sizing:border-box}body{margin:0;background:#080b12;color:#f5f7ff;font-family:Manrope,system-ui;min-height:100vh;background-image:radial-gradient(circle at 12% -5%,#5443c640,transparent 34%),radial-gradient(circle at 92% 15%,#05c6b430,transparent 25%)}
.shell{max-width:1440px;margin:auto;padding:25px 34px 50px}.top{display:flex;justify-content:space-between;align-items:center;border-bottom:1px solid #ffffff15;padding-bottom:23px}.brand{display:flex;gap:12px;align-items:center;font-weight:800;letter-spacing:-.7px;font-size:20px}.bolt{display:grid;place-items:center;width:34px;height:34px;border-radius:11px;background:linear-gradient(135deg,#7c5cff,#1ee6c1);box-shadow:0 0 28px #785cff80}.live{font:12px 'DM Mono';color:#94a0b9;display:flex;gap:8px;align-items:center}.live i{width:8px;height:8px;border-radius:99px;background:#25d7a1;box-shadow:0 0 12px #25d7a1}.hero{display:flex;justify-content:space-between;gap:30px;padding:49px 0 34px}.eyebrow{font:12px 'DM Mono';letter-spacing:1.1px;color:#8f82ff;text-transform:uppercase}.hero h1{font-size:clamp(35px,5vw,64px);line-height:1.03;letter-spacing:-3px;margin:14px 0;max-width:780px}.hero h1 em{font-style:normal;background:linear-gradient(90deg,#9f8cff,#31e2cb);color:transparent;background-clip:text}.hero p{color:#9da9bf;max-width:590px;line-height:1.6}.button{align-self:end;background:#edeaff;color:#16122c;border:0;border-radius:10px;padding:13px 17px;font-weight:800;cursor:pointer}.grid{display:grid;grid-template-columns:1.35fr .65fr;gap:18px}.card{background:#10151fbd;border:1px solid #ffffff10;border-radius:17px;padding:21px;box-shadow:0 20px 50px #0000002b}.label{font:11px 'DM Mono';color:#72809a;text-transform:uppercase;letter-spacing:1px}.issue{display:flex;justify-content:space-between;margin-top:15px}.issue h2{margin:4px 0;font-size:22px;letter-spacing:-.8px}.tag{height:max-content;font:11px 'DM Mono';padding:6px 8px;border-radius:6px;background:#17233a;color:#82b8ff}.timeline{margin-top:23px;border-left:1px solid #364056;padding-left:20px}.step{position:relative;margin:0 0 19px}.step:before{content:'';position:absolute;left:-25px;top:3px;width:9px;height:9px;border-radius:50%;background:#293248;border:3px solid #10151f}.step.done:before{background:#22d8a8;box-shadow:0 0 13px #22d8a8}.step.active:before{background:#987cff;box-shadow:0 0 15px #987cff}.step b{display:block;font-size:13px}.step span{font-size:12px;color:#8290a8}.status{display:flex;gap:11px;align-items:center;background:#121a28;border-radius:10px;padding:12px;margin-top:17px}.status strong{font-size:13px}.status small{color:#8290a8;display:block}.gauge{margin-left:auto;color:#35dfbd;font:16px 'DM Mono'}.policy{display:grid;gap:9px;margin-top:16px}.check{display:flex;justify-content:space-between;padding:11px;background:#111925;border-radius:9px;font-size:12px}.check span:last-child{color:#35dfbd;font-family:'DM Mono'}.side h3{font-size:17px;margin:7px 0 16px}.metric{padding:16px 0;border-bottom:1px solid #ffffff0d}.metric strong{font-size:31px;letter-spacing:-2px}.metric small{display:block;color:#8190a8;margin-top:3px}.pr{margin-top:18px;background:linear-gradient(130deg,#1a2033,#182b31);border:1px solid #48dab83d;border-radius:12px;padding:14px}.pr b{font-size:13px}.pr p{font:11px 'DM Mono';color:#8ea2b7}.bar{height:5px;background:#273143;border-radius:6px;overflow:hidden;margin-top:8px}.bar i{display:block;width:78%;height:100%;background:linear-gradient(90deg,#8d72ff,#2de3c0)}@media(max-width:800px){.shell{padding:20px}.hero{display:block}.button{margin-top:15px}.grid{grid-template-columns:1fr}.hero h1{letter-spacing:-2px}}
</style></head><body><main class="shell"><header class="top"><div class="brand"><div class="bolt">ϟ</div> NIGHTSHIFT</div><div class="live"><i></i> SYSTEMS OPERATIONAL · US-CENTRAL1</div></header><section class="hero"><div><div class="eyebrow">Autonomous maintenance command center</div><h1>From approved issue<br>to <em>tested draft PR.</em></h1><p>NightShift works in the background, keeping every decision visible, bounded, and ready for human review.</p></div><button class="button" onclick="document.querySelector('.active').scrollIntoView({behavior:'smooth'})">View live run →</button></section><section class="grid"><article class="card"><div class="label">Current autonomous run</div><div class="issue"><div><h2>Empty search results crash the page</h2><span class="label">Issue #42 · karthik7271/nightshift</span></div><span class="tag">agent-ready</span></div><div class="timeline"><div class="step done"><b>Issue qualified</b><span>Approved repository · bounded bug label</span></div><div class="step done"><b>Context assembled</b><span>2 source files · 1 regression test</span></div><div class="step active"><b>Plan verified</b><span>Awaiting isolated branch creation</span></div><div class="step"><b>Run CI</b><span>GitHub Actions check suite</span></div><div class="step"><b>Open draft PR</b><span>Human merge required</span></div></div><div class="status"><div><strong>Scope confidence</strong><small>All deterministic policy gates passed</small></div><div class="gauge">92%</div></div></article><aside class="card side"><div class="label">Safety posture</div><h3>Autonomy you can audit</h3><div class="policy"><div class="check"><span>Branch isolation</span><span>PASS</span></div><div class="check"><span>Max 3 changed files</span><span>PASS</span></div><div class="check"><span>No auth / CI / dependency edits</span><span>PASS</span></div><div class="check"><span>Human merge authority</span><span>ENFORCED</span></div></div><div class="metric"><strong>0</strong><small>unbounded actions taken</small></div><div class="metric"><strong>1</strong><small>approval required before merge</small></div><div class="pr"><b>Draft PR will include</b><p>change summary · CI evidence · risk notes · rollback guidance</p><div class="bar"><i></i></div></div></aside></section></main></body></html>'''
